   527      // sometimes there are MDL7 files which have a monochrome
   528      // texture instead of material colors ... posssible they have
   529      // been converted to MDL7 from other formats, such as MDL5
   530      aiColor4D clrTexture;
   531      if (pcNew)
   532          clrTexture = ReplaceTextureWithColor(pcNew.get());
   533      else
   534          clrTexture.r = get_qnan();
   535
   536      // check whether a material definition is contained in the skin
   537      if (iType & AI_MDL7_SKINTYPE_MATERIAL) {
   538          BE_NCONST MDL::Material_MDL7 *pcMatIn = (BE_NCONST MDL::Material_MDL7 *)szCurrent;
   539          szCurrent = (unsigned char *)(pcMatIn + 1);
   540          VALIDATE_FILE_SIZE(szCurrent);
   541
   542          aiColor3D clrTemp;
   543
   544  #define COLOR_MULTIPLY_RGB()         \
   545      if (is_not_qnan(clrTexture.r)) { \
   546          clrTemp.r *= clrTexture.r;   \
   547          clrTemp.g *= clrTexture.g;   \
   548          clrTemp.b *= clrTexture.b;   \
   549      }
   550
   551          // read diffuse color
   552          clrTemp.r = pcMatIn->Diffuse.r;
   553          AI_SWAP4(clrTemp.r);
   554          clrTemp.g = pcMatIn->Diffuse.g;
   555          AI_SWAP4(clrTemp.g);
   556          clrTemp.b = pcMatIn->Diffuse.b;
   557          AI_SWAP4(clrTemp.b);
   558          COLOR_MULTIPLY_RGB();
   559          pcMatOut->AddProperty<aiColor3D>(&clrTemp, 1, AI_MATKEY_COLOR_DIFFUSE);
   560
   561          // read specular color
   562          clrTemp.r = pcMatIn->Specular.r;
   563          AI_SWAP4(clrTemp.r);
   564          clrTemp.g = pcMatIn->Specular.g;
   565          AI_SWAP4(clrTemp.g);
   566          clrTemp.b = pcMatIn->Specular.b;
   567          AI_SWAP4(clrTemp.b);
   568          COLOR_MULTIPLY_RGB();
   569          pcMatOut->AddProperty<aiColor3D>(&clrTemp, 1, AI_MATKEY_COLOR_SPECULAR);
   570
   571          // read ambient color
   572          clrTemp.r = pcMatIn->Ambient.r;
   573          AI_SWAP4(clrTemp.r);
   574          clrTemp.g = pcMatIn->Ambient.g;
   575          AI_SWAP4(clrTemp.g);
   576          clrTemp.b = pcMatIn->Ambient.b;
   577          AI_SWAP4(clrTemp.b);
   578          COLOR_MULTIPLY_RGB();
   579          pcMatOut->AddProperty<aiColor3D>(&clrTemp, 1, AI_MATKEY_COLOR_AMBIENT);
   580
   581          // read emissive color
   582          clrTemp.r = pcMatIn->Emissive.r;
   583          AI_SWAP4(clrTemp.r);
   584          clrTemp.g = pcMatIn->Emissive.g;
   585          AI_SWAP4(clrTemp.g);
   586          clrTemp.b = pcMatIn->Emissive.b;
   587          AI_SWAP4(clrTemp.b);
   588          pcMatOut->AddProperty<aiColor3D>(&clrTemp, 1, AI_MATKEY_COLOR_EMISSIVE);
   589
   590  #undef COLOR_MULITPLY_RGB
   591
   592          // FIX: Take the opacity from the ambient color.
   593          // The doc say something else, but it is fact that MED exports the
   594          // opacity like this .... oh well.
   595          clrTemp.r = pcMatIn->Ambient.a;
   596          AI_SWAP4(clrTemp.r);
   597          if (is_not_qnan(clrTexture.r)) {
   598              clrTemp.r *= clrTexture.a;
   599          }
   600          pcMatOut->AddProperty<ai_real>(&clrTemp.r, 1, AI_MATKEY_OPACITY);
   601
   602          // read phong power
   603          int iShadingMode = (int)aiShadingMode_Gouraud;
   604          AI_SWAP4(pcMatIn->Power);
   605          if (0.0f != pcMatIn->Power) {
   606              iShadingMode = (int)aiShadingMode_Phong;
   607              // pcMatIn is packed, we can't form pointers to its members
   608              float power = pcMatIn->Power;
   609              pcMatOut->AddProperty<float>(&power, 1, AI_MATKEY_SHININESS);
   610          }
   611          pcMatOut->AddProperty<int>(&iShadingMode, 1, AI_MATKEY_SHADING_MODEL);
   612      } else if (is_not_qnan(clrTexture.r)) {
   613          pcMatOut->AddProperty<aiColor4D>(&clrTexture, 1, AI_MATKEY_COLOR_DIFFUSE);
   614          pcMatOut->AddProperty<aiColor4D>(&clrTexture, 1, AI_MATKEY_COLOR_SPECULAR);
   615      }
   616      // if the texture could be replaced by a single material color
   617      // we don't need the texture anymore
   618      if (is_not_qnan(clrTexture.r)) {
   619          pcNew.reset();
   620      }
   621
   622      // If an ASCII effect description (HLSL?) is contained in the file,
   623      // we can simply ignore it ...
   624      if (iType & AI_MDL7_SKINTYPE_MATERIAL_ASCDEF) {
   625          VALIDATE_FILE_SIZE(szCurrent);
   626          int32_t iMe = *((int32_t *)szCurrent);
   627          AI_SWAP4(iMe);
   628          szCurrent += sizeof(char) * iMe + sizeof(int32_t);
   629          VALIDATE_FILE_SIZE(szCurrent);
   630      }
   631
   632      // If an embedded texture has been loaded setup the corresponding
   633      // data structures in the aiScene instance
   634      if (pcNew && pScene->mNumTextures <= 999) {
   635          // place this as diffuse texture
   636          char current[5];
   637          ai_snprintf(current, 5, "*%i", this->pScene->mNumTextures);
   638
   639          aiString szFile;
   640          const size_t iLen = strlen((const char *)current);
   641          ::memcpy(szFile.data, (const char *)current, iLen + 1);
   642          szFile.length = (ai_uint32)iLen;
   643
   644          pcMatOut->AddProperty(&szFile, AI_MATKEY_TEXTURE_DIFFUSE(0));
   645
   646          // store the texture
   647          if (!pScene->mNumTextures) {
   648              pScene->mNumTextures = 1;
   649              pScene->mTextures = new aiTexture *[1];
   650              pScene->mTextures[0] = pcNew.release();
   651          } else {
   652              aiTexture **pc = pScene->mTextures;
   653              pScene->mTextures = new aiTexture *[pScene->mNumTextures + 1];
   654              for (unsigned int i = 0; i < pScene->mNumTextures; ++i) {
   655                  pScene->mTextures[i] = pc[i];
   656              }
   657
   658              pScene->mTextures[pScene->mNumTextures] = pcNew.release();
   659              pScene->mNumTextures++;
   660              delete[] pc;
   661          }
   662      }
   663      VALIDATE_FILE_SIZE(szCurrent);
   664      *szCurrentOut = szCurrent;
   665  }
