   667  // ------------------------------------------------------------------------------------------------
   668  // Skip a skin lump
   669  void MDLImporter::SkipSkinLump_3DGS_MDL7(
   670          const unsigned char *szCurrent,
   671          const unsigned char **szCurrentOut,
   672          unsigned int iType,
   673          unsigned int iWidth,
   674          unsigned int iHeight) {
   675      // get the type of the skin
   676      const unsigned int iMasked = (unsigned int)(iType & 0xF);
   677
   678      if (0x6 == iMasked) {
   679          szCurrent += iWidth;
   680      }
   681      if (0x7 == iMasked) {
   682          const size_t iLen = std::strlen((const char *)szCurrent);
   683          szCurrent += iLen + 1;
   684      } else if (iMasked || !iType) {
   685          if (iMasked || !iType || (iType && iWidth && iHeight)) {
   686              // ParseTextureColorData(..., aiTexture::pcData == bad_texel) will simply
   687              // return the size of the color data in bytes in iSkip
   688              unsigned int iSkip = 0;
   689
   690              aiTexture tex;
   691              tex.pcData = bad_texel;
   692              tex.mHeight = iHeight;
   693              tex.mWidth = iWidth;
   694              ParseTextureColorData(szCurrent, iMasked, &iSkip, &tex);
   695
   696              // FIX: Important, otherwise the destructor will crash
   697              tex.pcData = nullptr;
   698
   699              // skip length of texture data
   700              szCurrent += iSkip;
   701          }
   702      }
   703
   704      // check whether a material definition is contained in the skin
   705      if (iType & AI_MDL7_SKINTYPE_MATERIAL) {
   706          BE_NCONST MDL::Material_MDL7 *pcMatIn = (BE_NCONST MDL::Material_MDL7 *)szCurrent;
   707          szCurrent = (unsigned char *)(pcMatIn + 1);
   708      }
   709
   710      // if an ASCII effect description (HLSL?) is contained in the file,
   711      // we can simply ignore it ...
   712      if (iType & AI_MDL7_SKINTYPE_MATERIAL_ASCDEF) {
   713          int32_t iMe = *((int32_t *)szCurrent);
   714          AI_SWAP4(iMe);
   715          szCurrent += sizeof(char) * iMe + sizeof(int32_t);
   716      }
   717      *szCurrentOut = szCurrent;
   718  }
